window.addEventListener('resize',()=>{if(!renderer)return;const w=sceneHost.clientWidth,h=sceneHost.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()});
const species=[
 {name:'Embercub',type:'FLAME',emoji:'🔥',max:38,color:0xe78655,move:'Cinder Pounce',power:12},
 {name:'Mossling',type:'GROVE',emoji:'🌿',max:34,color:0x80a76f,move:'Bramble Bonk',power:10},
 {name:'Tidekip',type:'TIDE',emoji:'💧',max:40,color:0x67b5bd,move:'Bubble Pop',power:11},
 {name:'Voltkit',type:'SPARK',emoji:'⚡',max:32,color:0xd9b849,move:'Static Dash',power:13},
 {name:'Pebblit',type:'STONE',emoji:'🪨',max:46,color:0x9b8973,move:'Rock Roll',power:10}
];
const moves=[
 {name:'Cinder Pounce',kind:'FLAME',power:13,desc:'FLAME · Power 13',key:'1'},
 {name:'Quick Swipe',kind:'NORMAL',power:9,desc:'NORMAL · Power 9',key:'2'},
 {name:'Wild Spark',kind:'SPARK',power:11,desc:'SPARK · Power 11',key:'3'},
 {name:'Soothing Berry',kind:'HEAL',power:15,desc:'ITEM · Restore 15 HP',key:'4'}
];
let party=[{species:species[0],hp:38,level:5,xp:0}],active=0,enemy=null,encounter=1,locked=true,finished=false,turns=0;
const $=s=>document.querySelector(s),controls=$('#controls');
function makeEnemy(){const pool=[species[1],species[2],species[3],species[4]],sp=pool[(encounter-1)%pool.length];const level=3+encounter;return{species:sp,hp:sp.max+encounter*3,max:sp.max+encounter*3,level}}
function current(){return party[active]}
function setMessage(s){$('#message').textContent=s}
function updateBars(){if(!enemy)return;const p=current(),eh=Math.max(0,enemy.hp),ph=Math.max(0,p.hp),em=enemy.max||enemy.species.max,pm=p.species.max+(p.level-5)*4;$('#foeName').textContent=enemy.species.name;$('#foeLevel').textContent=`LV. ${enemy.level}`;$('#foeType').textContent=`✦ ${enemy.species.type}`;$('#foeHp').style.width=`${Math.max(0,eh/em*100)}%`;$('#foeHp').style.background=eh/em<.25?'linear-gradient(90deg,#eb6c5a,#f3a05e)':eh/em<.5?'linear-gradient(90deg,#e7b65f,#ecd47c)':'';$('#foeHpText').textContent=`${eh} / ${em}`;$('#playerName').textContent=p.species.name;$('#playerLevel').textContent=`LV. ${p.level}`;$('#playerType').textContent=`✦ ${p.species.type}`;$('#playerHp').style.width=`${Math.max(0,ph/pm*100)}%`;$('#playerHp').style.background=ph/pm<.25?'linear-gradient(90deg,#eb6c5a,#f3a05e)':ph/pm<.5?'linear-gradient(90deg,#e7b65f,#ecd47c)':'';$('#playerHpText').textContent=`${ph} / ${pm}`;$('#xp').style.width=`${p.xp}%`;$('#round').textContent=`WILD ENCOUNTER · ${String(encounter).padStart(2,'0')}`}
function renderControls(){controls.innerHTML='';moves.forEach((m,i)=>{const b=document.createElement('button');b.className='action'+(i===0?' primary':'');b.disabled=locked||finished||(i===3&&current().hp>=current().species.max+(current().level-5)*4);b.innerHTML=`<strong>${i===0?current().species.move:m.name}</strong><span>${i===0?`${current().species.type} · Power ${current().species.power}`:m.desc}</span><b class="key">${m.key}</b>`;b.addEventListener('click',()=>act(i));controls.appendChild(b)});const team=document.createElement('button');team.className='action';team.disabled=locked||finished;team.innerHTML=`<strong>Team & switch</strong><span>VIEW ALLIES · ${party.length} CREATURE${party.length===1?'':'S'}</span><b class="key">T</b>`;team.addEventListener('click',openTeam);controls.appendChild(team);const flee=document.createElement('button');flee.className='action';flee.disabled=locked||finished;flee.innerHTML='<strong>Forfeit</strong><span>END THIS ENCOUNTER</span>';flee.addEventListener('click',()=>endGame(false));controls.appendChild(flee)}
function sparkle(target,color=0xffd277,count=12){if(!scene||!target)return;const world=new THREE.Vector3();target.getWorldPosition(world);for(let i=0;i<count;i++){const p=new THREE.Mesh(new THREE.SphereGeometry(.045+Math.random()*.045,6,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}));p.position.copy(world).add(new THREE.Vector3((Math.random()-.5)*1.3,Math.random()*1.5,(Math.random()-.5)*.8));p.userData.v=new THREE.Vector3((Math.random()-.5)*.045,Math.random()*.06,(Math.random()-.5)*.03);p.userData.life=.45+Math.random()*.5;scene.add(p);particles.push(p)}}
function popToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),900)}
function animateHit(target){if(!target)return;const original=target.position.x;target.position.x=original+(target===foeMesh?-.42:.42);setTimeout(()=>{if(target)target.position.x=original},180)}
function act(index){if(locked||finished)return;locked=true;renderControls();const p=current();if(index===3){const max=p.species.max+(p.level-5)*4;const amount=Math.min(15,max-p.hp);if(amount<=0){setMessage(`${p.species.name} is already at full health.`);locked=false;renderControls();return}p.hp+=amount;setMessage(`${p.species.name} munched a Soothing Berry and recovered ${amount} HP!`);sparkle(playerMesh,0x9addaa,16);updateBars();return enemyTurn(850)}const move=index===0?{name:p.species.move,type:p.species.type,power:p.species.power}:{name:moves[index].name,type:moves[index].kind,power:moves[index].power};const weak=(move.type==='FLAME'&&enemy.species.type==='GROVE')||(move.type==='GROVE'&&enemy.species.type==='TIDE')||(move.type==='TIDE'&&enemy.species.type==='FLAME')||(move.type==='SPARK'&&enemy.species.type==='TIDE');const resist=(move.type==='FLAME'&&enemy.species.type==='TIDE')||(move.type==='TIDE'&&enemy.species.type==='GROVE')||(move.type==='GROVE'&&enemy.species.type==='FLAME');let damage=Math.max(3,Math.round((move.power+Math.floor(Math.random()*5)+p.level-5)*(weak?1.45:resist?.72:1)));enemy.hp=Math.max(0,enemy.hp-damage);setMessage(`${p.species.name} used ${move.name}! ${weak?'It was super effective!':resist?'The foe resisted the hit.':`It dealt ${damage} damage.`}`);sparkle(foeMesh,move.type==='FLAME'?0xffa653:move.type==='SPARK'?0xffef79:0x9ce5c5,15);animateHit(foeMesh);updateBars();if(enemy.hp<=0){setTimeout(victory,700);return}enemyTurn(900)}
function enemyTurn(delay=700){setTimeout(()=>{if(finished)return;const p=current();const damage=Math.max(3,Math.round((5+Math.random()*5+enemy.level*.6)*(enemy.species.type==='FLAME'&&p.species.type==='GROVE'?1.3:1)));p.hp=Math.max(0,p.hp-damage);setMessage(`${enemy.species.name} counterattacked! ${p.species.name} took ${damage} damage.`);sparkle(playerMesh,0xff8671,12);animateHit(playerMesh);updateBars();if(p.hp<=0){const next=party.findIndex((c,i)=>i!==active&&c.hp>0);if(next>=0){setTimeout(()=>{active=next;setMessage(`${p.species.name} needs a rest. Go, ${current().species.name}!`);sparkle(playerMesh,0xffd277,15);updateBars();locked=false;renderControls()},800)}else setTimeout(()=>endGame(false),800);return}locked=false;renderControls()},delay)}
function victory(){const p=current();p.xp+=35+encounter*5;if(p.xp>=100){p.xp-=100;p.level++;p.hp=Math.min(p.species.max+(p.level-5)*4,p.hp+8);popToast('LEVEL UP!')}let recruit=enemy.species;if(party.length<3&&!party.some(c=>c.species===recruit)){party.push({species:recruit,hp:recruit.max,level:Math.max(3,enemy.level),xp:0});setMessage(`${enemy.species.name} joined your team! ${p.species.name} earned experience.`)}else setMessage(`${enemy.species.name} dashed back into the wild! ${p.species.name} gained experience.`);updateBars();renderControls();if(encounter>=3){setTimeout(()=>endGame(true),1100);return}locked=true;renderControls();$('#turnLabel').textContent='ENCOUNTER WON';setTimeout(()=>{encounter++;enemy=makeEnemy();foeMesh.visible=true;setMessage(`A new wild ${enemy.species.name} stepped into the clearing!`);$('#turnLabel').textContent='YOUR TURN';updateBars();locked=false;renderControls()},1500)}
function endGame(won){finished=true;locked=true;renderControls();$('#modalTitle').textContent=won?'Mistwood is at peace!':'Your adventure pauses here';$('#modalText').textContent=won?`Your team won ${encounter} encounters and brought harmony back to the clearing. Your creatures are ready for another adventure.`:'Your team needs a little rest. The wilds will be waiting when you return.';$('#startButton').textContent=won?'PLAY AGAIN':'TRY AGAIN';$('#overlay').style.display='grid'}
function reset(){party=[{species:species[0],hp:38,level:5,xp:0}];active=0;encounter=1;enemy=makeEnemy();finished=false;locked=false;$('#overlay').style.display='none';$('#turnLabel').textContent='YOUR TURN';$('#message').textContent='A wild Mossling emerged from the mist!';foeMesh.visible=true;updateBars();renderControls()}
function openTeam(){if(locked||finished)return;const list=$('#teamList');list.innerHTML='';party.forEach((c,i)=>{const row=document.createElement('div');row.className='team-item';row.innerHTML=`<span class="team-emoji">${c.species.emoji}</span><div class="team-info"><strong>${c.species.name} ${i===active?'· ACTIVE':''}</strong><small>LV. ${c.level} · ${Math.max(0,c.hp)} / ${c.species.max+(c.level-5)*4} HP · ${c.species.type}</small></div>`;const b=document.createElement('button');b.className='switchbtn';b.textContent=i===active?'IN BATTLE':'SWITCH';b.disabled=i===active||c.hp<=0;b.addEventListener('click',()=>{active=i;$('#inventory').classList.remove('open');locked=true;renderControls();setMessage(`Come on, ${c.species.name}!`);sparkle(playerMesh,0xe6d280,14);updateBars();enemyTurn(650)});row.appendChild(b);list.appendChild(row)});$('#inventory').classList.add('open')}
$('#startButton').addEventListener('click',reset);$('#closeInventory').addEventListener('click',()=>$('#inventory').classList.remove('open'));$('#inventory').addEventListener('click',e=>{if(e.target.id==='inventory')$('#inventory').classList.remove('open')});window.addEventListener('keydown',e=>{if(e.key==='Escape')$('#inventory').classList.remove('open');if(e.key.toLowerCase()==='t'&&!locked)openTeam();if(!locked&&['1','2','3','4'].includes(e.key))act(Number(e.key)-1)});
enemy=makeEnemy();updateBars();renderControls();
</script>
</main>
