(async()=>{const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--enable-unsafe-swiftshader']});const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});const errors=[];page.on('pageerror',e=>errors.push('PAGE '+e.message));page.on('console',m=>{if(m.type()==='error')errors.push('CONSOLE '+m.text())});await page.goto('http://localhost:3002');await page.waitForTimeout(1000);await page.getByText('ENTER THE CLEARING').click();await page.waitForTimeout(300);await page.locator('#controls .action').first().click();await page.waitForTimeout(1200);const result={canvas:await page.locator('canvas').count(),message:await page.locator('#message').innerText(),overflow:await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),errors};await page.screenshot({path:'screenshots/wildbound.jpg',type:'jpeg',quality:70});console.log(JSON.stringify(result,null,2));await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
